/// F9: four menu triggers carry a caret and Settings stays a direct action.
/// The caret has no element id, so it is pinned by geometry: it is the only
/// variable in the trigger's trailing slot, and it is what pushes the three
/// seven-letter triggers past the caret-free eight-letter Settings button.
#[gpui_kit::test]
fn f09_nav_carets_and_ellipsis_rule(cx: &mut TestAppContext) {
    use gpui_kit::Keystroke;
    cx.update(gpui_kit::init);
    cx.update(|cx| cx.set_reduce_motion(true));
    let store = Store::open_in_memory().expect("in-memory store opens");
    let (_view, cx) = mount_view(store, cx);
    paint_frame(cx);

    let trigger_width = |cx: &mut VisualTestContext, id: &str| -> gpui_kit::Pixels {
        cx.update(|window, _| {
            window
                .try_find(id.to_string())
                .unwrap_or_else(|| panic!("{id} renders"))
                .bounds()
                .size
                .width
        })
    };
    // Measured floors: a caret adds ~13px to the label-only button.
    for (id, floor) in [
        ("program-menu", px(95.)),
        ("groups-menu", px(95.)),
        ("routing-menu", px(95.)),
        ("tools-menu", px(78.)),
    ] {
        let width = trigger_width(cx, id);
        assert!(
            width >= floor,
            "{id} holds the caret slot: {width:?} >= {floor:?}"
        );
    }
    let settings = trigger_width(cx, "settings-menu");
    assert!(
        settings <= px(88.),
        "Settings stays a direct action with no caret: {settings:?}"
    );
    // "Program", "Library" and "Routing" are shorter words than "Settings";
    // without a caret they would sit under it, so the caret is the difference.
    for id in ["program-menu", "groups-menu", "routing-menu"] {
        let width = trigger_width(cx, id);
        assert!(
            width > settings,
            "{id} is wider than the caret-free Settings trigger: {width:?} > {settings:?}"
        );
    }

    // The ellipsis marks only a surface that needs input before it applies.
    assert_eq!(
        label_of("groups-menu", cx),
        "Library",
        "a menu trigger needs no ellipsis"
    );
    let open = |cx: &mut VisualTestContext, trigger: &'static str| {
        cx.update(|window, cx| window.click(trigger, cx));
        cx.run_until_parked();
        paint_frame(cx);
        cx.run_until_parked();
        paint_frame(cx);
    };
    let close = |cx: &mut VisualTestContext| {
        cx.update(|window, cx| {
            let escape = Keystroke::parse("escape").expect("test keystroke parses");
            window.dispatch_keystroke(escape, cx);
        });
        cx.run_until_parked();
        paint_frame(cx);
    };

    open(cx, "program-menu");
    assert_eq!(
        label_of("export-library", cx),
        "Export…",
        "Export asks first"
    );
    assert_eq!(
        label_of("about-dialog", cx),
        "About",
        "About applies at once"
    );
    close(cx);

    open(cx, "groups-menu");
    assert_eq!(
        label_of("subscriptions", cx),
        "Subscriptions…",
        "Subscriptions asks first"
    );
    assert_eq!(
        label_of("menu-groups-dialog", cx),
        "Groups…",
        "Groups asks first"
    );
    assert_eq!(
        label_of("prune-clear-tests", cx),
        "Clear tests",
        "a confirm applies on one click, no ellipsis"
    );
    assert_eq!(
        label_of("prune-duplicates", cx),
        "Remove duplicates",
        "prune rows are confirms, no ellipsis"
    );
    close(cx);

    open(cx, "tools-menu");
    assert_eq!(
        label_of("menu-row-columns", cx),
        "Row columns",
        "Row columns applies on the spot, no ellipsis"
    );
    close(cx);
}

#[gpui_kit::test]
fn cua07_program_menu_uia_walk_matches_fixture(cx: &mut TestAppContext) {
    cx.update(gpui_kit::init);
    cx.update(|cx| cx.set_reduce_motion(true));
    let store = Store::open_in_memory().expect("in-memory store opens");
    let (_view, cx) = mount_view(store, cx);
    paint_frame(cx);
    cx.update(|window, cx| {
        window.click("program-menu", cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    cx.run_until_parked();
    paint_frame(cx);
    let fixture: serde_json::Value =
        serde_json::from_str(include_str!("../tests/fixtures/uia-program-menu.json"))
            .expect("program menu fixture parses");
    // K8/A1-3: the toolbar cluster owns intake; PROGRAM keeps Export/About
    // only, so the duplicate Add/Import entries stay retired.
    for retired in [
        "menu-add-config",
        "menu-import-config",
        "import-clipboard",
        "import-files",
    ] {
        assert!(
            cx.update(|window, _| window.try_find(retired.to_string()).is_none()),
            "{retired} stays out of the PROGRAM menu"
        );
    }
    let items = fixture["items"].as_array().expect("fixture lists items");
    let names: Vec<&str> = items
        .iter()
        .map(|item| item["name"].as_str().expect("fixture name"))
        .collect();
    for expected in ["Export", "About"] {
        assert!(
            names.iter().any(|name| name.contains(expected)),
            "PROGRAM walk names {expected}: {names:?}"
        );
    }
    for item in items {
        let id = item["id"].as_str().expect("fixture id");
        let (role, label) = cx.update(|window, _| {
            let snapshot = window
                .try_find(id.to_string())
                .unwrap_or_else(|| panic!("{id} renders in the PROGRAM menu"));
            (
                snapshot.role().map(|role| format!("{role:?}")),
                snapshot.label().map(str::to_string),
            )
        });
        assert_eq!(
            role.as_deref(),
            Some(item["role"].as_str().expect("fixture role")),
            "{id} exposes its fixture role"
        );
        assert_eq!(
            label.as_deref(),
            item["name"].as_str(),
            "{id} announces its fixture name"
        );
    }
    cx.update(|window, cx| {
        use gpui_kit::Keystroke;
        let escape = Keystroke::parse("escape").expect("test keystroke parses");
        window.dispatch_keystroke(escape, cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
}

#[gpui_kit::test]
fn cua07_card_context_menu_exposes_every_pinned_item(cx: &mut TestAppContext) {
    cx.update(gpui_kit::init);
    cx.update(|cx| cx.set_reduce_motion(true));
    let mut store = Store::open_in_memory().expect("in-memory store opens");
    let row = store
        .add(row19_seed("Work", "a.example.com", "10801"))
        .expect("seed works");
    let (_view, cx) = mount_view(store, cx);
    paint_frame(cx);
    cx.run_until_parked();
    paint_frame(cx);
    let card = format!("row-card-{}", row.id);
    assert!(
        cx.update(|window, _| window.try_find(card.clone()).is_some()),
        "seeded card paints"
    );
    cx.update(|window, cx| {
        window.right_click(card.clone(), cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    cx.run_until_parked();
    paint_frame(cx);
    let fixture: serde_json::Value =
        serde_json::from_str(include_str!("../tests/fixtures/uia-card-context-menu.json"))
            .expect("card menu fixture parses");
    // K8/A6-2: six core verbs render as id-pinned rows; `Reset…` and `More ▾`
    // are kit submenu rows (label-pinned, they carry no element id), so the
    // closed-menu walk sees exactly these six.
    fn assert_fixture_item(
        cx: &mut VisualTestContext,
        id: &str,
        name: &str,
        role: &str,
        scope: &str,
    ) {
        let (found_role, label) = cx.update(|window, _| {
            let snapshot = window
                .try_find(id.to_string())
                .unwrap_or_else(|| panic!("{id} renders in {scope}"));
            (
                snapshot.role().map(|role| format!("{role:?}")),
                snapshot.label().map(str::to_string),
            )
        });
        assert_eq!(
            found_role.as_deref(),
            Some(role),
            "{id} exposes its fixture role"
        );
        assert_eq!(
            label.as_deref(),
            Some(name),
            "{id} announces its fixture name"
        );
    }
    let items = fixture["items"].as_array().expect("fixture lists items");
    assert_eq!(items.len(), 6, "card menu pins exactly 6 core rows");
    for item in items {
        let verb = item["verb"].as_str().expect("fixture verb");
        assert_fixture_item(
            cx,
            &format!("rowctx-{verb}-{}", row.id),
            item["name"].as_str().expect("fixture name"),
            item["role"].as_str().expect("fixture role"),
            "the card menu",
        );
    }

    let labels: Vec<String> = cx.update(|window, _| {
        gpui_kit::base::test_support::snapshots(window)
            .iter()
            .filter_map(|snapshot| snapshot.label().map(str::to_string))
            .collect()
    });
    assert!(
        labels.iter().any(|label| label == "Reset…"),
        "the Reset… submenu row renders: {labels:?}"
    );
    assert!(
        labels.iter().any(|label| label == "More ▾"),
        "the More ▾ submenu row renders: {labels:?}"
    );

    let wanted: std::collections::HashSet<String> = items
        .iter()
        .map(|item| {
            format!(
                "rowctx-{}-{}",
                item["verb"].as_str().expect("fixture verb"),
                row.id
            )
        })
        .collect();
    let observed: Vec<String> = cx.update(|window, _| {
        gpui_kit::base::test_support::snapshots(window)
            .iter()
            .filter_map(|snapshot| {
                snapshot.path().last().and_then(|last| {
                    let id = format!("{last:?}");
                    if id.contains("rowctx-") {
                        Some(id)
                    } else {
                        None
                    }
                })
            })
            .collect()
    });
    assert_eq!(
        observed.len(),
        6,
        "card menu walks exactly 6 core rows, no seventh: {observed:?}"
    );
    for id in &observed {
        assert!(
            wanted.iter().any(|want| id.contains(want)),
            "walked node {id} is one of the 6 pinned rows"
        );
    }

    // Keyboard: Up from no selection lands on the LAST row (More ▾), whose
    // submenu paints the demoted verbs.
    fn press_key(cx: &mut VisualTestContext, key: &str) {
        cx.update(|window, cx| {
            let stroke = gpui_kit::Keystroke::parse(key).expect("test keystroke parses");
            window.dispatch_keystroke(stroke, cx);
        });
        cx.run_until_parked();
        paint_frame(cx);
    }
    press_key(cx, "up");
    for item in fixture["more"].as_array().expect("fixture lists More") {
        let verb = item["verb"].as_str().expect("fixture verb");
        assert_fixture_item(
            cx,
            &format!("rowctx-{verb}-{}", row.id),
            item["name"].as_str().expect("fixture name"),
            item["role"].as_str().expect("fixture role"),
            "the More ▾ submenu",
        );
    }

    // K8: the Speedtest / Resolve Out-IP / Resolve domain verbs are retired —
    // they appear in no menu at all.
    for verb in ["speedtest", "out-ip", "resolve-domain"] {
        let id = format!("rowctx-{verb}-{}", row.id);
        assert!(
            cx.update(|window, _| window.try_find(id.clone()).is_none()),
            "{id} is retired from every menu"
        );
    }

    // …and `More ▾` reads top → bottom as Move to group · Copy URLs · Share… ·
    // Duplicate · Ping.
    let more_items = fixture["more"].as_array().expect("fixture lists More");
    assert_eq!(more_items.len(), 5, "More ▾ pins exactly 5 rows");
    let mut more_order = Vec::new();
    for item in more_items {
        let verb = item["verb"].as_str().expect("fixture verb");
        let id = format!("rowctx-{verb}-{}", row.id);
        let bounds = cx.update(|window, _| {
            window
                .try_find(id.clone())
                .unwrap_or_else(|| panic!("{id} renders in the More ▾ submenu"))
                .bounds()
        });
        more_order.push((bounds.origin.y, bounds.origin.x));
    }
    for pair in more_order.windows(2) {
        assert!(
            pair[0].0 < pair[1].0,
            "More ▾ order is Move to group · Copy URLs · Share… · Duplicate · Ping: {more_order:?}"
        );
    }

    // …and two Ups further (delete → Reset…) open the Reset… submenu.
    press_key(cx, "up");
    press_key(cx, "up");
    for item in fixture["reset"].as_array().expect("fixture lists Reset") {
        let verb = item["verb"].as_str().expect("fixture verb");
        assert_fixture_item(
            cx,
            &format!("rowctx-{verb}-{}", row.id),
            item["name"].as_str().expect("fixture name"),
            item["role"].as_str().expect("fixture role"),
            "the Reset… submenu",
        );
    }
    cx.update(|window, cx| {
        use gpui_kit::Keystroke;
        let escape = Keystroke::parse("escape").expect("test keystroke parses");
        window.dispatch_keystroke(escape, cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
}

#[gpui_kit::test]
fn cua07_menus_keyboard_operable(cx: &mut TestAppContext) {
    use gpui_kit::Keystroke;
    cx.update(gpui_kit::init);
    cx.update(|cx| cx.set_reduce_motion(true));
    let mut store = Store::open_in_memory().expect("in-memory store opens");
    let row = store
        .add(row19_seed("Work", "a.example.com", "10801"))
        .expect("seed works");
    let (_view, cx) = mount_view(store, cx);
    paint_frame(cx);
    cx.update(|window, cx| {
        window.click("program-menu", cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    cx.update(|window, cx| {
        let down = Keystroke::parse("down").expect("test keystroke parses");
        window.dispatch_keystroke(down, cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    cx.update(|window, cx| {
        let enter = Keystroke::parse("enter").expect("test keystroke parses");
        window.dispatch_keystroke(enter, cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    assert!(
        cx.update(|window, cx| window.has_active_dialog(cx)),
        "Enter on the first PROGRAM item opens Export"
    );
    let before = notification_count(cx);
    cx.update(|window, cx| {
        let escape = Keystroke::parse("escape").expect("test keystroke parses");
        window.dispatch_keystroke(escape, cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    assert!(
        !cx.update(|window, cx| window.has_active_dialog(cx)),
        "Esc closes Add"
    );
    assert_eq!(notification_count(cx), before, "Esc commits nothing");
    let card = format!("row-card-{}", row.id);
    cx.update(|window, cx| {
        window.right_click(card.clone(), cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    let edit = format!("rowctx-edit-{}", row.id);
    assert!(
        cx.update(|window, _| window.try_find(edit.clone()).is_some()),
        "card menu opens from the keyboard path too"
    );
    cx.update(|window, cx| {
        let escape = Keystroke::parse("escape").expect("test keystroke parses");
        window.dispatch_keystroke(escape, cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    assert!(
        cx.update(|window, _| window.try_find(edit.clone()).is_none()),
        "Esc dismisses the card menu"
    );
}

