#[test]
fn library_search_matches_host_bind_port() {
    use crate::store::ProxyConfig;
    use crate::LibraryDelegate;
    use manyproxy_core::library_row_matches;
    fn row(name: &str, server: &str, bind: &str, port: u16) -> ProxyConfig {
        ProxyConfig {
            id: format!("id-{name}"),
            name: name.to_string(),
            protocol: "vless".to_string(),
            params: format!("{{\"type\":\"vless\",\"server\":\"{server}\",\"server_port\":443}}"),
            group: "default".to_string(),
            enabled: false,
            bind_ip: bind.to_string(),
            port,
            subscription_id: None,
            identity_key: None,
            preset_id: None,
        }
    }
    let alpha = row("Alpha", "a.example.com", "127.0.0.1", 10801);
    let beta = row("Beta", "10.0.0.5", "10.0.0.5", 10802);
    assert!(library_row_matches(&beta, "10.0.0.5"), "bind/host match");
    assert!(library_row_matches(&alpha, "10801"), "port match");
    assert!(!library_row_matches(&beta, "a.example.com"));
    assert!(library_row_matches(&alpha, "a.example.com"), "host match");
    assert!(library_row_matches(&alpha, "alpha"), "name still matches");
    assert!(
        library_row_matches(&alpha, "vless"),
        "protocol still matches"
    );
    assert!(!library_row_matches(&alpha, "nope"), "no false positive");

    let mut delegate = LibraryDelegate::new();
    delegate.set_rows(vec![alpha, beta]);
    delegate.query = "10.0.0.5".to_string();
    delegate.apply_filter();
    assert_eq!(
        delegate.visible.len(),
        1,
        "filter narrows to the bind/host row"
    );
    delegate.query = "10801".to_string();
    delegate.apply_filter();
    assert_eq!(delegate.visible.len(), 1, "filter narrows by port");
    delegate.query = String::new();
    delegate.apply_filter();
    assert_eq!(delegate.visible.len(), 2, "empty query shows all");
}

#[test]
fn t47_search_index_matches_scan_parity() {
    use crate::store::ProxyConfig;
    use crate::LibraryDelegate;
    fn row(
        id: &str,
        name: &str,
        protocol: &str,
        params: &str,
        group: &str,
        bind: &str,
        port: u16,
    ) -> ProxyConfig {
        ProxyConfig {
            id: id.to_string(),
            name: name.to_string(),
            protocol: protocol.to_string(),
            params: params.to_string(),
            group: group.to_string(),
            enabled: true,
            bind_ip: bind.to_string(),
            port,
            subscription_id: None,
            identity_key: None,
            preset_id: None,
        }
    }
    let rows = vec![
        row(
            "1",
            "Alpha",
            "vless",
            r#"{"server":"a.example.com","server_port":443}"#,
            "g1",
            "127.0.0.1",
            10801,
        ),
        row(
            "2",
            "Beta",
            "trojan",
            r#"{"address":"10.0.0.9","port":"8443"}"#,
            "G2",
            "::1",
            10802,
        ),
        row(
            "3",
            "Gamma Ray",
            "WIREGUARD",
            "not json{{{",
            "",
            "0.0.0.0",
            10803,
        ),
        row(
            "4",
            "Unicodae",
            "ss",
            r#"{"server":"X.EXAMPLE.COM","server_port":8388,"password":"s3cret"}"#,
            "vpn",
            "192.168.1.2",
            10804,
        ),
        row(
            "5",
            "both-hosts",
            "vless",
            r#"{"server":"nomatch.invalid","address":"matchme.invalid"}"#,
            "g1",
            "127.0.0.1",
            10805,
        ),
        row(
            "6",
            "numport",
            "tuic",
            r#"{"server":"h.example.com","server_port":12345}"#,
            "g3",
            "127.0.0.1",
            10806,
        ),
    ];
    for query in [
        "",
        "  ",
        "ALPHA",
        "vless",
        "WIREGUARD",
        "a.example.com",
        "X.EXAMPLE",
        "1080",
        "8443",
        "g1",
        "G2",
        "::1",
        "0.0.0.0",
        "gamma ray",
        "matchme",
        "nomatch",
        "s3cret",
        "nope",
        "alpha vless",
        "8388",
    ] {
        let mut delegate = LibraryDelegate::new();
        delegate.set_rows(rows.clone());
        delegate.query = query.to_string();
        delegate.apply_filter();
        let cached: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        let expected: Vec<String> = rows
            .iter()
            .filter(|r| manyproxy_core::library_row_matches(r, query))
            .map(|r| r.id.clone())
            .collect();
        assert_eq!(cached, expected, "index parity for query {query:?}");
    }
}

#[test]
fn t47_search_index_matches_full_with_context() {
    use crate::store::ProxyConfig;
    use crate::LibraryDelegate;
    use manyproxy_core::{library_row_matches_full, MatchContext};
    fn row(id: &str, name: &str, enabled: bool, sub: Option<&str>) -> ProxyConfig {
        ProxyConfig {
            id: id.to_string(),
            name: name.to_string(),
            protocol: "vless".to_string(),
            params: r#"{"server":"a.example.com","server_port":443}"#.to_string(),
            group: "g".to_string(),
            enabled,
            bind_ip: "127.0.0.1".to_string(),
            port: 10801,
            subscription_id: sub.map(str::to_string),
            identity_key: None,
            preset_id: None,
        }
    }
    let rows = vec![
        row("1", "Alpha", true, Some("s1")),
        row("2", "Beta", false, None),
    ];
    let mut ctx = MatchContext::default();
    ctx.sub_labels
        .insert("s1".to_string(), "Nightly Sub".to_string());
    ctx.running.insert("1".to_string());
    ctx.health.insert("1".to_string(), "87ms".to_string());
    ctx.health.insert("2".to_string(), "dead".to_string());
    let mut delegate = LibraryDelegate::new();
    delegate.set_rows(rows.clone());
    delegate.set_running(vec!["1".to_string()]);
    delegate.set_health(ctx.health.clone());
    delegate.set_search_context(ctx.sub_labels.clone(), ctx.preset_names.clone());
    for query in [
        "nightly",
        "sub",
        "enabled",
        "disabled",
        "running",
        "stopped",
        "live",
        "dead",
        "87ms",
        "untested",
        "alpha",
        "zzz-no-match",
    ] {
        delegate.query = query.to_string();
        delegate.apply_filter();
        let cached: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        let expected: Vec<String> = rows
            .iter()
            .filter(|r| library_row_matches_full(r, query, &ctx))
            .map(|r| r.id.clone())
            .collect();
        assert_eq!(cached, expected, "index/full parity for {query:?}");
    }
}

fn t73_port_row(
    id: &str,
    name: &str,
    protocol: &str,
    group: &str,
    port: u16,
) -> crate::store::ProxyConfig {
    crate::store::ProxyConfig {
        id: id.to_string(),
        name: name.to_string(),
        protocol: protocol.to_string(),
        params: r#"{"server":"t73.example.com","server_port":443}"#.to_string(),
        group: group.to_string(),
        enabled: true,
        bind_ip: "127.0.0.1".to_string(),
        port,
        subscription_id: None,
        identity_key: None,
        preset_id: None,
    }
}

fn t73_visible_ports(delegate: &crate::LibraryDelegate) -> Vec<u16> {
    delegate
        .visible
        .iter()
        .map(|&index| delegate.rows[index].port)
        .collect()
}

fn t73_filtered(rows: Vec<crate::store::ProxyConfig>, query: &str) -> (Vec<u16>, String) {
    let mut delegate = crate::LibraryDelegate::new();
    delegate.set_rows(rows);
    delegate.query = query.to_string();
    delegate.apply_filter();
    (t73_visible_ports(&delegate), delegate.active_filter_text())
}

fn t73_rows() -> Vec<crate::store::ProxyConfig> {
    vec![
        t73_port_row("a", "Alpha", "vless", "g1", 10801),
        t73_port_row("b", "Beta", "vless", "g1", 10802),
        t73_port_row("c", "Gamma", "vmess", "g2", 10910),
        t73_port_row("d", "Delta", "trojan", "g2", 20000),
    ]
}

#[test]
fn t73_port_filter_exact_and_ranges() {
    use crate::PortPredicate;

    assert_eq!(
        crate::parse_port_predicate("port=10801:10910"),
        Some(PortPredicate {
            lo: 10801,
            hi: 10910
        }),
        "range token parses"
    );
    assert_eq!(
        crate::parse_port_predicate("port=10801"),
        Some(PortPredicate {
            lo: 10801,
            hi: 10801
        }),
        "exact token is a one-wide range"
    );

    let (exact, text) = t73_filtered(t73_rows(), "port=10801");
    assert_eq!(exact, vec![10801], "exact port matches only that port");
    assert_eq!(text, "port: 10801..10801", "canonical filter text");

    let (range, text) = t73_filtered(t73_rows(), "port=10801:10910");
    assert_eq!(range, vec![10801, 10802, 10910], "range is inclusive");
    assert_eq!(text, "port: 10801..10910", "canonical range text");

    let (case_insensitive, _) = t73_filtered(t73_rows(), "PORT=10802");
    assert_eq!(
        case_insensitive,
        vec![10802],
        "port key is case-insensitive"
    );

    let (reversed, text) = t73_filtered(t73_rows(), "port=10910:10801");
    assert!(
        reversed.is_empty(),
        "reversed bounds never behave as a range"
    );
    assert_eq!(
        text, "search: \"port=10910:10801\"",
        "reversed bounds stay literal text"
    );

    let (as_text, _) = t73_filtered(t73_rows(), "1080");
    assert_eq!(
        as_text,
        vec![10801, 10802],
        "bare digits keep today's substring behavior"
    );
}

#[test]
fn t73_port_filter_open_ended_forms() {
    let (open_top, text) = t73_filtered(t73_rows(), "port=10801:");
    assert_eq!(open_top, vec![10801, 10802, 10910, 20000], "N..=65535");
    assert_eq!(text, "port: 10801..65535", "open top renders the ceiling");

    let (open_bottom, text) = t73_filtered(t73_rows(), "port=:10802");
    assert_eq!(open_bottom, vec![10801, 10802], "0..=M");
    assert_eq!(text, "port: 0..10802", "open bottom renders the floor");

    let (everything, _) = t73_filtered(t73_rows(), "port=0:");
    assert_eq!(
        everything,
        vec![10801, 10802, 10910, 20000],
        "0: spans every u16 port"
    );

    let (ceiling, _) = t73_filtered(t73_rows(), "port=65535:");
    assert!(ceiling.is_empty(), "65535: is a valid empty range");
}

#[test]
fn t73_malformed_port_token_renders_literal() {
    use crate::LibraryDelegate;

    for token in [
        "port=",
        "port=x",
        "port=:",
        "port=5:1",
        "port=65536",
        "port=10801-10802",
        "port",
    ] {
        assert_eq!(
            crate::parse_port_predicate(token),
            None,
            "{token:?} is not a port predicate"
        );
    }

    let rows = vec![
        t73_port_row("a", "Alpha", "vless", "g1", 10801),
        t73_port_row("b", "port=x", "vless", "g1", 10803),
        t73_port_row("c", "port=5:1", "vless", "g1", 10804),
    ];

    let (hits, text) = t73_filtered(rows.clone(), "port=x");
    assert_eq!(
        hits,
        vec![10803],
        "port=x matches the row literally named port=x, not by port"
    );
    assert_eq!(
        text, "search: \"port=x\"",
        "a malformed token keeps today's filter phrasing"
    );

    let (reversed, _) = t73_filtered(rows.clone(), "port=5:1");
    assert_eq!(
        reversed,
        vec![10804],
        "a reversed range is literal text, not an error"
    );

    let (prefix, _) = t73_filtered(rows.clone(), "port=");
    assert_eq!(
        prefix,
        vec![10803, 10804],
        "port= is a literal substring of both names"
    );

    let (nonsense, _) = t73_filtered(rows.clone(), "port=:");
    assert!(nonsense.is_empty(), "port=: neither parses nor matches");

    let (overflow, _) = t73_filtered(rows.clone(), "port=65536");
    assert!(
        overflow.is_empty(),
        "out-of-u16 value is literal, not a panic"
    );

    let mut delegate = LibraryDelegate::new();
    delegate.set_rows(rows);
    delegate.query = "port=".to_string();
    delegate.apply_filter();
    assert_eq!(
        delegate.query, "port=",
        "the query string itself is never rewritten"
    );
}

#[test]
fn t73_port_composes_with_facets() {
    use crate::{FacetStatus, LibraryDelegate};

    let mut delegate = LibraryDelegate::new();
    delegate.set_rows(vec![
        t73_port_row("1", "Alpha", "vless", "g1", 10801),
        t73_port_row("2", "Alpha Two", "vless", "g2", 10802),
        t73_port_row("3", "Beta", "vmess", "g1", 10803),
    ]);
    delegate.query = "port=10801:10803 alpha".to_string();
    delegate.apply_filter();
    assert_eq!(
        t73_visible_ports(&delegate),
        vec![10801, 10802],
        "the text part keeps today's substring behavior inside the range"
    );

    delegate.set_facet_group(Some("g1".to_string()));
    assert_eq!(
        t73_visible_ports(&delegate),
        vec![10801],
        "group facet ANDs with the port predicate"
    );
    delegate.set_facet_group(Some("g2".to_string()));
    assert_eq!(t73_visible_ports(&delegate), vec![10802]);
    delegate.set_facet_group(None);

    // K11: the protocol dropdown retired; the search text still matches
    // protocol words through the row search index.
    delegate.query = "port=10801:10803 alpha vmess".to_string();
    delegate.apply_filter();
    assert!(
        t73_visible_ports(&delegate).is_empty(),
        "protocol words match as text and AND with the other tokens — no alpha row is vmess"
    );

    delegate.query = "port=10801:10803".to_string();
    delegate.apply_filter();
    delegate.set_running(vec!["3".to_string()]);
    delegate.set_health(
        [("3".to_string(), "dead".to_string())]
            .into_iter()
            .collect(),
    );
    delegate.set_facet_status(Some(FacetStatus::Dead));
    assert_eq!(t73_visible_ports(&delegate), vec![10803]);
    delegate.set_facet_status(None);

    delegate.query = "port=10801:10803 port=99999".to_string();
    delegate.apply_filter();
    assert!(
        t73_visible_ports(&delegate).is_empty(),
        "a second port= token degrades to literal text (pinned)"
    );

    delegate.query = "port=10801:10803".to_string();
    delegate.apply_filter();
    let mut unsorted = t73_visible_ports(&delegate);
    delegate.set_sort(crate::store::LibrarySort::new(
        crate::store::LibrarySortKey::TypeSecurity,
        crate::store::SortDirection::Ascending,
    ));
    let mut sorted = t73_visible_ports(&delegate);
    unsorted.sort_unstable();
    sorted.sort_unstable();
    assert_eq!(
        unsorted, sorted,
        "the type/security sort only reorders what the filter kept"
    );
}

#[gpui_kit::test]
fn t73_last_query_meta_restores_on_launch(cx: &mut TestAppContext) {
    use gpui_kit::Focusable as _;

    cx.update(gpui_kit::init);
    // Fixed name (no PID suffix): the delete below runs before any
    // connection exists, so it self-heals the previous run's leftovers;
    // a PID suffix made the final delete fail while the view still held
    // the connection and accumulated one run's files per suite pass.
    let path = std::env::temp_dir().join("manyproxy-t73-last-query.db");
    let _ = std::fs::remove_file(&path);
    let _ = std::fs::remove_file(path.with_extension("db-wal"));
    let _ = std::fs::remove_file(path.with_extension("db-shm"));
    {
        let mut store = Store::open_file(&path).expect("file store opens");
        assert_eq!(
            store.library_last_query(),
            None,
            "a fresh store remembers nothing"
        );
        store
            .set_library_last_query("port=10801")
            .expect("memory writes");
        assert_eq!(
            store.library_last_query().as_deref(),
            Some("port=10801"),
            "memory round-trips"
        );
        store.clear_library_last_query().expect("clear writes");
        assert_eq!(store.library_last_query(), None, "cleared reads as absent");
        store
            .set_library_last_query("   ")
            .expect("blank write is accepted");
        assert_eq!(
            store
                .get_meta(Store::META_LIBRARY_LAST_QUERY)
                .expect("meta read"),
            None,
            "a blank query never leaves a meta row behind"
        );
        store
            .add(facet_seed("Alpha", "vless", "travel", "10801"))
            .expect("seed works");
        store
            .add(facet_seed("Beta", "vless", "travel", "10802"))
            .expect("seed works");
    }

    let store = Store::open_file(&path).expect("reopen works");
    let (view, cx) = mount_view(store, cx);
    cx.run_until_parked();
    paint_frame(cx);
    assert_eq!(
        view.read_with(cx, |view, cx| view
            .search_input
            .read(cx)
            .value()
            .to_string()),
        "",
        "empty default opens with an empty search field"
    );
    assert_eq!(
        view.read_with(cx, |view, _| view
            .store
            .get_meta(Store::META_LIBRARY_LAST_QUERY)
            .expect("meta read")),
        None,
        "the empty default writes no meta row"
    );

    // Type through the real input: `set_value` emits no Change event, so
    // keystrokes are the honest way to exercise the persistence path.
    let handle = view.read_with(cx, |view, cx| view.search_input.read(cx).focus_handle(cx));
    cx.update(|window, cx| {
        window.focus(&handle, cx);
    });
    cx.simulate_input("port=10801");
    cx.run_until_parked();
    paint_frame(cx);
    let (typed_query, typed_ports) = view.read_with(cx, |view, cx| {
        let delegate = view.libraries.read(cx).delegate();
        (delegate.query.clone(), t73_visible_ports(delegate))
    });
    assert_eq!(
        typed_query, "port=10801",
        "typed query reaches the delegate"
    );
    assert_eq!(typed_ports, vec![10801], "typed port filter applies");
    assert_eq!(
        view.read_with(cx, |view, _| view.store.library_last_query())
            .as_deref(),
        Some("port=10801"),
        "typing remembers the query"
    );

    drop(view);
    let store = Store::open_file(&path).expect("restart reopen works");
    assert_eq!(
        store.library_last_query().as_deref(),
        Some("port=10801"),
        "the memory survives a clean restart"
    );
    let (restarted, cx) = mount_view(store, cx);
    cx.run_until_parked();
    paint_frame(cx);
    let (input_value, restored_query, restored_ports) = restarted.read_with(cx, |view, cx| {
        let delegate = view.libraries.read(cx).delegate();
        (
            view.search_input.read(cx).value().to_string(),
            delegate.query.clone(),
            t73_visible_ports(delegate),
        )
    });
    assert_eq!(
        input_value, "port=10801",
        "the search field opens holding the last filter"
    );
    assert_eq!(restored_query, "port=10801", "the delegate adopts it");
    assert_eq!(
        restored_ports,
        vec![10801],
        "the last filter is applied on launch"
    );

    cx.update(|window, cx| {
        window.click("clear-search", cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    let (cleared_query, cleared_memory) = restarted.read_with(cx, |view, cx| {
        (
            view.libraries.read(cx).delegate().query.clone(),
            view.store
                .get_meta(Store::META_LIBRARY_LAST_QUERY)
                .expect("meta read"),
        )
    });
    assert_eq!(
        cleared_query,
        String::new(),
        "clear search empties the query"
    );
    assert_eq!(
        cleared_memory, None,
        "clear search clears the visible memory too"
    );
    // Drop the view (and its store connection) before deleting so the
    // final cleanup actually succeeds on Windows.
    drop(restarted);
    let _ = std::fs::remove_file(&path);
}

#[test]
fn t44_facets_and_with_text_query() {
    use crate::store::ProxyConfig;
    use crate::{FacetStatus, LibraryDelegate};
    fn row(id: &str, name: &str, protocol: &str, group: &str, enabled: bool) -> ProxyConfig {
        ProxyConfig {
            id: id.to_string(),
            name: name.to_string(),
            protocol: protocol.to_string(),
            params: r#"{"server":"a.example.com","server_port":443}"#.to_string(),
            group: group.to_string(),
            enabled,
            bind_ip: "127.0.0.1".to_string(),
            port: 10801,
            subscription_id: None,
            identity_key: None,
            preset_id: None,
        }
    }
    let rows = vec![
        row("1", "Alpha", "vless", "team", true),
        row("2", "Beta", "vmess", "team", false),
        row("3", "Gamma", "vless", "lab", true),
    ];
    let mut delegate = LibraryDelegate::new();
    delegate.set_rows(rows);
    delegate.set_running(vec!["1".to_string()]);
    let mut health = std::collections::HashMap::new();
    health.insert("1".to_string(), "87ms".to_string());
    health.insert("3".to_string(), "dead".to_string());
    delegate.set_health(health);

    delegate.query = "vless".to_string();
    delegate.apply_filter();
    assert_eq!(delegate.visible.len(), 2);

    delegate.set_facet_group(Some("team".to_string()));
    let shown: Vec<String> = delegate
        .visible
        .iter()
        .map(|&i| delegate.rows[i].id.clone())
        .collect();
    assert_eq!(shown, vec!["1".to_string()]);

    delegate.set_facet_status(Some(FacetStatus::Disabled));
    assert!(delegate.visible.is_empty(), "all predicates must hold");
    delegate.set_facet_status(Some(FacetStatus::Enabled));
    let shown: Vec<String> = delegate
        .visible
        .iter()
        .map(|&i| delegate.rows[i].id.clone())
        .collect();
    assert_eq!(shown, vec!["1".to_string()]);

    // K11: the enabled/disabled axis is a group-menu pick — one write sets both
    // slots, so the menu can never show two active choices.
    delegate.query = String::new();
    delegate.set_facet_menu(Some("team".to_string()), Some(FacetStatus::Disabled));
    let shown: Vec<String> = delegate
        .visible
        .iter()
        .map(|&i| delegate.rows[i].id.clone())
        .collect();
    assert_eq!(shown, vec!["2".to_string()]);
    delegate.set_facet_menu(Some("lab".to_string()), Some(FacetStatus::Enabled));
    let shown: Vec<String> = delegate
        .visible
        .iter()
        .map(|&i| delegate.rows[i].id.clone())
        .collect();
    assert_eq!(shown, vec!["3".to_string()]);

    // K11: the lamp tones are the endpoint-state axis. Row 1 serves with a live
    // probe, row 3 serves dead, row 2 is stopped — exactly the three lamps.
    delegate.set_running(vec!["1".to_string(), "3".to_string()]);
    delegate.set_facet_menu(None, Some(FacetStatus::Running));
    let shown: Vec<String> = delegate
        .visible
        .iter()
        .map(|&i| delegate.rows[i].id.clone())
        .collect();
    assert_eq!(shown, vec!["1".to_string()]);
    delegate.set_facet_status(Some(FacetStatus::Dead));
    let shown: Vec<String> = delegate
        .visible
        .iter()
        .map(|&i| delegate.rows[i].id.clone())
        .collect();
    assert_eq!(shown, vec!["3".to_string()]);
    delegate.set_facet_status(Some(FacetStatus::Stopped));
    let shown: Vec<String> = delegate
        .visible
        .iter()
        .map(|&i| delegate.rows[i].id.clone())
        .collect();
    assert_eq!(shown, vec!["2".to_string()]);
    delegate.set_facet_status(Some(FacetStatus::Disabled));
    let shown: Vec<String> = delegate
        .visible
        .iter()
        .map(|&i| delegate.rows[i].id.clone())
        .collect();
    assert_eq!(shown, vec!["2".to_string()]);

    delegate.query = "a".to_string();
    delegate.clear_facets();
    assert_eq!(delegate.visible.len(), 3);
    assert_eq!(delegate.query, "a");
}

#[test]
fn t44_checked_set_honest_label_and_prune() {
    use crate::store::ProxyConfig;
    use crate::LibraryDelegate;
    fn row(id: &str, name: &str, group: &str) -> ProxyConfig {
        ProxyConfig {
            id: id.to_string(),
            name: name.to_string(),
            protocol: "vless".to_string(),
            params: r#"{"server":"a.example.com"}"#.to_string(),
            group: group.to_string(),
            enabled: true,
            bind_ip: "127.0.0.1".to_string(),
            port: 10801,
            subscription_id: None,
            identity_key: None,
            preset_id: None,
        }
    }
    let mut delegate = LibraryDelegate::new();
    delegate.set_rows(vec![
        row("1", "Alpha", "g"),
        row("2", "Beta", "g"),
        row("3", "Gamma", "g"),
    ]);
    assert_eq!(delegate.bulk_label(), "");
    delegate.toggle_checked("1");
    delegate.toggle_checked("3");
    delegate.toggle_checked("ghost");
    assert_eq!(delegate.checked.len(), 2, "unknown ids never check");
    assert_eq!(delegate.bulk_label(), "2 checked · 3 shown");

    delegate.query = "alpha".to_string();
    delegate.apply_filter();
    assert_eq!(delegate.checked.len(), 2);
    assert_eq!(delegate.bulk_label(), "2 checked · 1 shown");
    let checked: Vec<String> = delegate
        .checked_rows()
        .iter()
        .map(|r| r.id.clone())
        .collect();
    assert_eq!(checked, vec!["1".to_string(), "3".to_string()]);

    delegate.query = String::new();
    delegate.set_facet_group(Some("nope".to_string()));
    assert_eq!(delegate.bulk_label(), "2 checked · 0 shown");
    delegate.clear_facets();

    delegate.set_rows(vec![row("1", "Alpha", "g"), row("2", "Beta", "g")]);
    assert_eq!(delegate.checked.len(), 1);
    assert_eq!(delegate.bulk_label(), "1 checked · 2 shown");
    delegate.toggle_checked("1");
    assert_eq!(delegate.bulk_label(), "");
    delegate.clear_checked();
    assert_eq!(delegate.bulk_label(), "");
}

#[test]
fn t09_show_security_and_type_security_sort() {
    use crate::apply_show_security;
    use crate::store::ProxyConfig;
    use crate::LibraryDelegate;
    fn row(id: &str, name: &str, protocol: &str, params: &str) -> ProxyConfig {
        ProxyConfig {
            id: id.to_string(),
            name: name.to_string(),
            protocol: protocol.to_string(),
            params: params.to_string(),
            group: "g".to_string(),
            enabled: true,
            bind_ip: "127.0.0.1".to_string(),
            port: 10801,
            subscription_id: None,
            identity_key: None,
            preset_id: None,
        }
    }
    let tls_row = row("1", "A", "vless", r#"{"security":"tls"}"#);
    let mut cell = "a.example.com:443".to_string();
    apply_show_security(&mut cell, &tls_row);
    assert_eq!(cell, "a.example.com:443 · tls", "posture spliced");
    let mut plain = "b.example.com:443".to_string();
    apply_show_security(&mut plain, &row("2", "B", "vmess", "{}"));
    assert_eq!(plain, "b.example.com:443 · none", "plain protocols labeled");
    let mut delegate = LibraryDelegate::new();
    delegate.set_rows(vec![
        row("1", "T", "trojan", "{}"),
        row("2", "Vtls", "vless", r#"{"security":"tls"}"#),
        row("3", "Vreal", "vless", r#"{"security":"reality"}"#),
    ]);
    let order = |delegate: &LibraryDelegate| {
        delegate
            .visible
            .iter()
            .map(|&index| delegate.rows[index].name.clone())
            .collect::<Vec<_>>()
    };
    assert_eq!(order(&delegate), vec!["T", "Vtls", "Vreal"]);
    // T-27: the toggle retired into the sort picker; the equivalent key
    // (direction is fixed for it) must order exactly as the toggle did.
    delegate.set_sort(crate::store::LibrarySort::new(
        crate::store::LibrarySortKey::TypeSecurity,
        crate::store::SortDirection::Ascending,
    ));
    assert_eq!(order(&delegate), vec!["T", "Vreal", "Vtls"]);
    assert_eq!(
        delegate
            .rows
            .iter()
            .map(|row| row.name.clone())
            .collect::<Vec<_>>(),
        vec!["T", "Vtls", "Vreal"],
        "store order untouched"
    );
    assert!(!delegate.show_security);
    delegate.set_show_security(true);
    assert!(delegate.show_security);
}

