#[test]
fn laneb_serving_tone_single_evidence_rule() {
    use crate::{serving_tone, ServingTone};
    assert_eq!(serving_tone(true, Some("dead"), false), ServingTone::Failed);
    assert_eq!(
        serving_tone(true, Some(" dead "), true),
        ServingTone::Failed
    );
    assert_eq!(
        serving_tone(true, Some("87ms"), false),
        ServingTone::Serving
    );
    assert_eq!(serving_tone(true, None, false), ServingTone::Serving);
    assert_eq!(
        serving_tone(false, Some("dead"), false),
        ServingTone::Stopped
    );
    assert_eq!(serving_tone(false, None, true), ServingTone::Stopped);
    assert_eq!(serving_tone(false, None, false), ServingTone::Stopped);
}

#[gpui_kit::test]
fn t04_detail_block_shelf_packs_modules_with_operate_row(cx: &mut TestAppContext) {
    use crate::health::{HealthKind, HealthSample, TestOutcome};
    use gpui_kit::component::IndexPath;
    use gpui_kit::point;
    cx.update(gpui_kit::init);
    let mut store = Store::open_in_memory().expect("in-memory store opens");
    let seeded = store
        .add(row19_seed("Work", "a.example.com", "10801"))
        .expect("seed works");
    let (view, cx) = mount_view(store, cx);

    cx.update(|_, cx| {
        view.update(cx, |view, cx| {
            view.libraries.update(cx, |state, list_cx| {
                state.delegate_mut().selected = Some(IndexPath::new(0));
                list_cx.notify();
            });
        });
    });
    cx.run_until_parked();
    open_inspector(&view, cx);
    paint_frame(cx);
    cx.run_until_parked();
    paint_frame(cx);

    assert_painted(cx, "detail-acting-on");

    assert_painted(cx, "config-endpoints");
    assert_within_frame(cx, "config-endpoints");
    assert!(
        cx.update(|window, _| window.try_find("detail-operate".to_string()).is_some()),
        "detail-operate renders the single operate row"
    );

    let operate_bounds = cx.update(|window, _| {
        window
            .try_find("detail-operate".to_string())
            .expect("operate row renders")
            .bounds()
    });
    assert!(
        operate_bounds.origin.x >= px(0.)
            && operate_bounds.origin.x + operate_bounds.size.width <= px(1000.) + px(1.),
        "operate row fits the frame width: {operate_bounds:?}"
    );
    let (endpoints_bottom, operate_top) = cx.update(|window, _| {
        let endpoints = window
            .try_find("config-endpoints".to_string())
            .expect("endpoints paints")
            .bounds();
        let operate = window
            .try_find("detail-operate".to_string())
            .expect("operate row paints")
            .bounds();
        (endpoints.origin.y + endpoints.size.height, operate.origin.y)
    });
    assert!(
        endpoints_bottom <= operate_top,
        "endpoints sit above the operate row: {endpoints_bottom:?} <= {operate_top:?}"
    );

    // K1/A4-8: one tier — Start · Stop · Test plus the `…` kebab. Ping, Logs
    // and Copy URLs moved into the kebab.
    for id in ["engine-start", "engine-stop", "health-test", "row-menu"] {
        assert!(
            cx.update(|window, _| window.try_find(id.to_string()).is_some()),
            "{id} rides the operate row"
        );
    }

    cx.update(|_, cx| {
        view.update(cx, |view, cx| {
            view.inspector_tab = crate::InspectorTab::Health;
            cx.notify();
        });
    });
    cx.update(|_, cx| {
        view.update(cx, |view, _cx| {
            view.health_store.record_outcome(&TestOutcome {
                sample: HealthSample {
                    config_id: seeded.id.clone(),
                    at: 1,
                    kind: HealthKind::UrlTest,
                    latency_ms: None,
                    error: Some("timeout".to_string()),
                },
                success: None,
            });
        });
    });
    cx.run_until_parked();
    paint_frame(cx);
    cx.run_until_parked();
    paint_frame(cx);

    assert_painted(cx, "config-health-alert");

    cx.update(|window, cx| {
        window.scroll(
            "config-detail-body",
            gpui_kit::ScrollDelta::Pixels(point(px(0.), px(-100_000.))),
            cx,
        );
    });
    cx.run_until_parked();
    paint_frame(cx);
    cx.run_until_parked();
    paint_frame(cx);
    assert_painted(cx, "config-health");
    assert!(
        cx.update(|window, _| window.try_find("detail-operate".to_string()).is_some()),
        "detail-operate renders on the Health pane row"
    );
    for id in ["engine-start", "health-test", "row-menu"] {
        assert!(
            cx.update(|window, _| window.try_find(id.to_string()).is_some()),
            "{id} operates on the Health pane row"
        );
    }
}

#[gpui_kit::test]
fn operate_row_reachable_on_every_inspector_tab(cx: &mut TestAppContext) {
    use gpui_kit::component::IndexPath;
    cx.update(gpui_kit::init);
    let mut store = Store::open_in_memory().expect("in-memory store opens");
    store
        .add(row19_seed("Work", "a.example.com", "10801"))
        .expect("seed works");
    let (view, cx) = mount_view(store, cx);
    cx.update(|_, cx| {
        view.update(cx, |view, cx| {
            view.libraries.update(cx, |state, list_cx| {
                state.delegate_mut().selected = Some(IndexPath::new(0));
                list_cx.notify();
            });
        });
    });
    for (tab, name) in [
        (crate::InspectorTab::Details, "Details"),
        (crate::InspectorTab::Health, "Health"),
        (crate::InspectorTab::Logs, "Logs"),
        (crate::InspectorTab::Links, "Links"),
        (crate::InspectorTab::Traffic, "Traffic"),
    ] {
        cx.update(|_, cx| {
            view.update(cx, |view, cx| {
                view.inspector_tab = tab;
                cx.notify();
            });
        });
        cx.run_until_parked();
        open_inspector(&view, cx);
        paint_frame(cx);
        cx.run_until_parked();
        paint_frame(cx);

        assert!(
            cx.update(|window, _| window.try_find("detail-operate".to_string()).is_some()),
            "{name}: detail-operate renders"
        );
        // K1/A4-2: the actions follow the content inside the ONE pane scroll —
        // not pinned to the panel bottom. Scrolling to the end brings the row
        // fully inside the 700px frame.
        cx.update(|window, cx| {
            window.scroll(
                "config-detail-body",
                gpui_kit::ScrollDelta::Pixels(point(px(0.), px(-100_000.))),
                cx,
            );
        });
        cx.run_until_parked();
        paint_frame(cx);
        let (operate_top, operate_bottom) = cx.update(|window, _| {
            let bounds = window
                .try_find("detail-operate".to_string())
                .expect("operate row renders")
                .bounds();
            (bounds.origin.y, bounds.origin.y + bounds.size.height)
        });
        assert!(
            operate_top >= px(0.) && operate_bottom <= px(700.) + px(1.),
            "{name}: operate row sits inside the 700px frame at the end of the \
             scroll, not clipped: {operate_top:?}..{operate_bottom:?}"
        );

        for id in ["engine-start", "engine-stop", "health-test", "row-menu"] {
            assert!(
                cx.update(|window, _| window.try_find(id.to_string()).is_some()),
                "{name}: {id} rides the operate row"
            );
        }
    }

    cx.update(|_, cx| {
        view.update(cx, |view, cx| {
            view.inspector_tab = crate::InspectorTab::Health;
            cx.notify();
        });
    });
    cx.run_until_parked();
    paint_frame(cx);
    cx.run_until_parked();
    paint_frame(cx);

    assert!(
        cx.update(|window, _| window.try_find("config-history".to_string()).is_some()),
        "History module renders"
    );
    assert!(
        cx.update(|window, _| window.try_find("config-history-few".to_string()).is_some()),
        "History states its empty case instead of painting a silent box"
    );
}

#[gpui_kit::test]
fn inspector_body_scrolls_to_reach_below_fold_sections(cx: &mut TestAppContext) {
    use gpui_kit::component::IndexPath;
    cx.update(gpui_kit::init);
    let mut store = Store::open_in_memory().expect("in-memory store opens");
    store
        .add(row19_seed("Work", "a.example.com", "10801"))
        .expect("seed works");
    let (view, cx) = mount_view(store, cx);
    let select_health_tab = |view: &Entity<AppView>, cx: &mut gpui_kit::VisualTestContext| {
        cx.update(|_, cx| {
            view.update(cx, |view, cx| {
                view.libraries.update(cx, |state, list_cx| {
                    state.delegate_mut().selected = Some(IndexPath::new(0));
                    list_cx.notify();
                });
                view.inspector_tab = crate::InspectorTab::Health;
                cx.notify();
            });
        });
        cx.run_until_parked();
        open_inspector(view, cx);
        paint_frame(cx);
        cx.run_until_parked();
        paint_frame(cx);
    };
    select_health_tab(&view, cx);

    // K1/A4-2: the pane is ONE scroll. At the 700px default the denser Health
    // pane now fits; paint the 620px minimum-height frame so the content
    // genuinely overflows and the scroll range is observable.
    paint_frame_at(cx, 1000., 620.);

    let max_offset = cx.update(|_, cx| view.read(cx).detail_scroll.max_offset());
    assert!(
        max_offset.y > px(0.),
        "the Health pane overflows the panel, so there is something below \
             the fold to scroll to: {max_offset:?}"
    );

    let scrolled = cx.update(|window, cx| {
        window.scroll(
            "config-detail-body",
            gpui_kit::ScrollDelta::Pixels(point(px(0.), px(-80.))),
            cx,
        );
        view.read(cx).detail_scroll.offset().y
    });
    assert!(
        scrolled < px(0.),
        "wheeling the inspector body scrolls it down: offset={scrolled:?}"
    );

    let over = cx.update(|window, cx| {
        window.scroll(
            "config-detail-body",
            gpui_kit::ScrollDelta::Pixels(point(px(0.), px(-100_000.))),
            cx,
        );
        let view = view.read(cx);
        (
            view.detail_scroll.offset().y,
            view.detail_scroll.max_offset().y,
        )
    });
    assert_eq!(
        over.0, -over.1,
        "the pane clamps at its maximum offset: {:?}",
        over
    );

    cx.update(|window, cx| {
        view.update(cx, |view, cx| {
            view.focus.focus(window, cx);
        });
    });
    cx.run_until_parked();
    cx.update(|window, cx| {
        window.dispatch_action(Box::new(crate::InspectorDetails), cx);
    });
    cx.run_until_parked();
    paint_frame(cx);
    cx.run_until_parked();
    paint_frame(cx);
    let (tab, offset) = cx.update(|_, cx| {
        let view = view.read(cx);
        (view.inspector_tab.index(), view.detail_scroll.offset().y)
    });
    assert_eq!(
        tab,
        crate::InspectorTab::Details.index(),
        "the action actually switched panes"
    );
    assert_eq!(
        offset,
        px(0.),
        "the Details pane starts scrolled to the top, not mid-history"
    );
}

